-- +goose Up
-- Consolidated Lindaflor schema (fresh baseline for the Go app). Equivalent
-- to the final state of the Rust migrations 0001..0030, folded into one
-- forward-only migration, with duplicate indexes dropped, plus the sqlc
-- nullable marker domains and the product_summaries view. Primary keys are
-- generated by the application (UUIDv7) unless a DEFAULT is given.
--
-- Conventions for later migrations: forward-only (no Down section),
-- `000NN_<what>.sql`, one concern per file.

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------

CREATE TYPE order_status AS ENUM (
    'pending_payment',
    'paid',
    'processing',
    'shipped',
    'delivered',
    'cancelled',
    'refunded'
);

CREATE TYPE pix_key_type AS ENUM ('cpf', 'cnpj', 'email', 'phone', 'random');

CREATE TYPE product_category AS ENUM (
    'biquini',
    'maio',
    'saida_praia',
    'acessorio',
    'biquini_top',
    'biquini_bottom'
);

CREATE TYPE product_size AS ENUM ('pp', 'p', 'm', 'g', 'gg');

CREATE TYPE review_fit AS ENUM ('pequeno', 'ideal', 'grande');

CREATE TYPE review_status AS ENUM ('pending', 'approved', 'rejected');

-- ---------------------------------------------------------------------------
-- sqlc nullable marker domains
-- ---------------------------------------------------------------------------

-- sqlc cannot infer that a computed expression (scalar subquery, CASE,
-- aggregate, column of a LEFT JOIN subquery) may be NULL: it types it as a
-- non-pointer Go value and the scan fails at runtime on NULL. Casting such
-- an expression to one of these domains (`(SELECT ...)::null_text`) makes
-- sqlc emit a pointer (see the overrides in sqlc.yaml). The domains carry
-- no constraint and Postgres reports the base type on the wire, so pgx
-- decodes them like the base type.
CREATE DOMAIN null_text AS text;
CREATE DOMAIN null_int4 AS integer;
CREATE DOMAIN null_int8 AS bigint;
CREATE DOMAIN null_bool AS boolean;
CREATE DOMAIN null_uuid AS uuid;
CREATE DOMAIN null_timestamptz AS timestamptz;

-- ---------------------------------------------------------------------------
-- Identity: users, accounts, sessions, verifications, two_factor
-- ---------------------------------------------------------------------------

CREATE TABLE users (
    id                 uuid PRIMARY KEY,
    name               text NOT NULL,
    email              text NOT NULL UNIQUE,
    email_verified     boolean NOT NULL DEFAULT false,
    image              text,
    two_factor_enabled boolean NOT NULL DEFAULT false,
    role               text,
    banned             boolean NOT NULL DEFAULT false,
    ban_reason         text,
    ban_expires        timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE accounts (
    id                       uuid PRIMARY KEY,
    account_id               text NOT NULL,
    provider_id              text NOT NULL,
    user_id                  uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    password                 text,
    access_token             text,
    refresh_token            text,
    id_token                 text,
    scope                    text,
    access_token_expires_at  timestamptz,
    refresh_token_expires_at timestamptz,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX accounts_user_id_idx ON accounts (user_id);

-- `token` holds sha256(raw token) — never the raw cookie value.
CREATE TABLE sessions (
    id              uuid PRIMARY KEY,
    token           text NOT NULL UNIQUE,
    user_id         uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    expires_at      timestamptz NOT NULL,
    ip_address      text,
    user_agent      text,
    impersonated_by uuid,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);

-- One-time tokens: `value` stays empty at rest, `value_hash` is the peppered
-- HMAC of the raw token.
CREATE TABLE verifications (
    id         uuid PRIMARY KEY,
    identifier text NOT NULL,
    value      text NOT NULL,
    value_hash text,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX verifications_identifier_idx ON verifications (identifier);
CREATE INDEX verifications_expires_at_idx ON verifications (expires_at);
CREATE UNIQUE INDEX verifications_identifier_value_hash_uidx ON verifications (identifier, value_hash);

-- TOTP secret is XChaCha20-Poly1305 encrypted at rest.
CREATE TABLE two_factor (
    id                 uuid PRIMARY KEY,
    user_id            uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    backup_codes       text NOT NULL,
    verified           boolean NOT NULL DEFAULT false,
    secret_nonce       bytea NOT NULL,
    secret_ciphertext  bytea NOT NULL,
    secret_key_version smallint NOT NULL DEFAULT 1
);
CREATE INDEX two_factor_user_id_idx ON two_factor (user_id);

CREATE TABLE user_addresses (
    id             uuid PRIMARY KEY,
    user_id        uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    label          text NOT NULL DEFAULT '',
    recipient_name text NOT NULL,
    zip_code       text NOT NULL CHECK (zip_code ~ '^[0-9]{8}$'),
    street         text NOT NULL,
    number         text NOT NULL,
    complement     text NOT NULL DEFAULT '',
    neighborhood   text NOT NULL,
    city           text NOT NULL,
    state          text NOT NULL CHECK (state ~ '^[A-Z]{2}$'),
    phone          text NOT NULL,
    is_default     boolean NOT NULL DEFAULT false,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX user_addresses_user_id_idx ON user_addresses (user_id);
CREATE UNIQUE INDEX user_addresses_one_default_uidx ON user_addresses (user_id) WHERE is_default;

-- Append-only privileged mutation trail.
CREATE TABLE audit_events (
    id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    aggregate_type text NOT NULL,
    aggregate_id   text NOT NULL,
    entity_type    text NOT NULL,
    entity_id      uuid NOT NULL,
    actor_user_id  uuid REFERENCES users (id) ON DELETE SET NULL,
    actor_name     text,
    metadata       jsonb NOT NULL DEFAULT '{}'::jsonb,
    occurred_at    timestamptz NOT NULL DEFAULT now(),
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_events_actor_idx ON audit_events (actor_user_id);
CREATE INDEX audit_events_aggregate_idx ON audit_events (aggregate_type, aggregate_id, occurred_at);
CREATE INDEX audit_events_entity_idx ON audit_events (entity_type, entity_id);

-- ---------------------------------------------------------------------------
-- Store settings (singleton row: id is always true)
-- ---------------------------------------------------------------------------

CREATE TABLE store_settings (
    id                            boolean PRIMARY KEY DEFAULT true
        CONSTRAINT store_settings_singleton CHECK (id),
    pix_key                       text,
    pix_key_type                  pix_key_type,
    pix_merchant_name             text,
    pix_merchant_city             text,
    whatsapp_number               text,
    whatsapp_message_template     text,
    free_shipping_threshold_cents bigint NOT NULL DEFAULT 29900,
    pix_discount_percent          smallint NOT NULL DEFAULT 5
        CONSTRAINT pix_discount_percent_check CHECK (pix_discount_percent >= 0 AND pix_discount_percent <= 30),
    announcement_text             text,
    first_purchase_coupon_code    text,
    created_at                    timestamptz NOT NULL DEFAULT now(),
    updated_at                    timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- Catalog: products, variants, images, looks, sets, banners
-- ---------------------------------------------------------------------------

CREATE TABLE products (
    id                        uuid PRIMARY KEY,
    name                      text NOT NULL,
    slug                      text NOT NULL,
    description               text,
    price_in_cents            bigint NOT NULL,
    compare_at_price_in_cents bigint,
    category                  product_category NOT NULL DEFAULT 'biquini',
    active                    boolean NOT NULL DEFAULT true,
    featured                  boolean NOT NULL DEFAULT false,
    created_at                timestamptz NOT NULL DEFAULT now(),
    updated_at                timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT compare_at_price_check
        CHECK (compare_at_price_in_cents IS NULL OR compare_at_price_in_cents > price_in_cents)
);
CREATE UNIQUE INDEX products_slug_uidx ON products (slug);
CREATE INDEX products_active_idx ON products (active);
CREATE INDEX products_storefront_idx ON products (active, featured, created_at DESC);

CREATE TABLE product_variants (
    id                  uuid PRIMARY KEY,
    product_id          uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    sku                 text NOT NULL,
    size                product_size NOT NULL,
    color               text NOT NULL,
    color_hex           text CONSTRAINT color_hex_check CHECK (color_hex IS NULL OR color_hex ~ '^#[0-9A-Fa-f]{6}$'),
    price_in_cents      bigint,
    low_stock_threshold integer NOT NULL DEFAULT 5,
    created_at          timestamptz NOT NULL DEFAULT now(),
    updated_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX product_variants_product_id_idx ON product_variants (product_id);
CREATE UNIQUE INDEX product_variants_sku_uidx ON product_variants (sku);

CREATE TABLE product_images (
    id         uuid PRIMARY KEY,
    product_id uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    url        text NOT NULL,
    alt        text,
    sort_order integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX product_images_product_id_idx ON product_images (product_id);

-- "Complete the look" pairings.
CREATE TABLE product_looks (
    product_id         uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    related_product_id uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    sort_order         integer NOT NULL DEFAULT 0,
    PRIMARY KEY (product_id, related_product_id),
    CONSTRAINT product_looks_check CHECK (product_id <> related_product_id)
);

CREATE TABLE sets (
    id                        uuid PRIMARY KEY,
    name                      text NOT NULL,
    slug                      text NOT NULL UNIQUE,
    description               text,
    price_in_cents            bigint,
    compare_at_price_in_cents bigint,
    active                    boolean NOT NULL DEFAULT true,
    created_at                timestamptz NOT NULL DEFAULT now(),
    updated_at                timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT sets_compare_at_price_check
        CHECK (compare_at_price_in_cents IS NULL OR compare_at_price_in_cents > price_in_cents)
);
CREATE INDEX sets_active_idx ON sets (active);

CREATE TABLE set_members (
    set_id     uuid NOT NULL REFERENCES sets (id) ON DELETE CASCADE,
    product_id uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    sort_order integer NOT NULL DEFAULT 0,
    PRIMARY KEY (set_id, product_id)
);
CREATE INDEX set_members_product_id_idx ON set_members (product_id);

CREATE TABLE set_images (
    id         uuid PRIMARY KEY,
    set_id     uuid NOT NULL REFERENCES sets (id) ON DELETE CASCADE,
    url        text NOT NULL,
    alt        text,
    sort_order integer NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX set_images_set_id_idx ON set_images (set_id);

CREATE TABLE set_slots (
    id         uuid PRIMARY KEY,
    set_id     uuid NOT NULL REFERENCES sets (id) ON DELETE CASCADE,
    label      text,
    sort_order integer NOT NULL DEFAULT 0
);
CREATE INDEX set_slots_set_id_idx ON set_slots (set_id);

CREATE TABLE set_slot_options (
    slot_id              uuid NOT NULL REFERENCES set_slots (id) ON DELETE CASCADE,
    variant_id           uuid NOT NULL REFERENCES product_variants (id) ON DELETE RESTRICT,
    price_override_cents bigint,
    PRIMARY KEY (slot_id, variant_id)
);
CREATE INDEX set_slot_options_variant_id_idx ON set_slot_options (variant_id);

CREATE TABLE home_banners (
    id         uuid PRIMARY KEY,
    title      text NOT NULL,
    subtitle   text,
    cta_label  text,
    link_url   text,
    image_url  text NOT NULL,
    sort_order integer NOT NULL DEFAULT 0,
    active     boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------
-- Inventory
-- ---------------------------------------------------------------------------

CREATE TABLE warehouses (
    id         uuid PRIMARY KEY,
    code       text NOT NULL,
    name       text NOT NULL,
    is_default boolean NOT NULL DEFAULT false,
    active     boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX warehouses_code_uidx ON warehouses (code);

CREATE TABLE inventory (
    id           uuid PRIMARY KEY,
    variant_id   uuid NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE,
    warehouse_id uuid NOT NULL REFERENCES warehouses (id) ON DELETE RESTRICT,
    quantity     integer NOT NULL DEFAULT 0,
    reserved     integer NOT NULL DEFAULT 0,
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT inventory_non_negative CHECK (quantity >= 0 AND reserved >= 0),
    CONSTRAINT inventory_reserved_not_over_quantity CHECK (reserved <= quantity)
);
CREATE UNIQUE INDEX inventory_variant_warehouse_uidx ON inventory (variant_id, warehouse_id);

-- ---------------------------------------------------------------------------
-- Coupons
-- ---------------------------------------------------------------------------

CREATE TABLE coupons (
    id                 uuid PRIMARY KEY,
    code               text NOT NULL,
    discount_type      text NOT NULL CHECK (discount_type IN ('fixed', 'percent')),
    discount_value     bigint NOT NULL CHECK (discount_value > 0),
    min_subtotal_cents bigint NOT NULL DEFAULT 0,
    max_discount_cents bigint CHECK (max_discount_cents IS NULL OR max_discount_cents > 0),
    active             boolean NOT NULL DEFAULT true,
    starts_at          timestamptz,
    expires_at         timestamptz,
    usage_type         text NOT NULL DEFAULT 'unlimited' CHECK (usage_type IN ('unique', 'unlimited')),
    max_uses           integer CHECK (max_uses IS NULL OR max_uses > 0),
    per_user_limit     integer NOT NULL DEFAULT 1 CHECK (per_user_limit > 0),
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT coupons_check CHECK (discount_type <> 'percent' OR (discount_value >= 1 AND discount_value <= 50))
);
CREATE UNIQUE INDEX coupons_code_upper_key ON coupons (upper(code));

CREATE TABLE coupon_assignments (
    coupon_id   uuid NOT NULL REFERENCES coupons (id) ON DELETE CASCADE,
    user_id     uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    assigned_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (coupon_id, user_id)
);
CREATE INDEX coupon_assignments_user_id_idx ON coupon_assignments (user_id);

-- ---------------------------------------------------------------------------
-- Carts
-- ---------------------------------------------------------------------------

CREATE TABLE carts (
    id                    uuid PRIMARY KEY,
    token                 uuid NOT NULL UNIQUE,
    user_id               uuid REFERENCES users (id) ON DELETE CASCADE,
    coupon_code           text,
    contact_email         text,
    abandoned_reminded_at timestamptz,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX carts_user_id_uidx ON carts (user_id) WHERE user_id IS NOT NULL;
CREATE INDEX carts_updated_at_idx ON carts (updated_at);
CREATE INDEX carts_guest_updated_at_idx ON carts (updated_at) WHERE user_id IS NULL;

-- A line is either a loose variant (set_id NULL) or one member of a set
-- bundle (set_id NOT NULL); each kind is unique per cart.
CREATE TABLE cart_items (
    id         uuid PRIMARY KEY,
    cart_id    uuid NOT NULL REFERENCES carts (id) ON DELETE CASCADE,
    variant_id uuid NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE,
    set_id     uuid REFERENCES sets (id) ON DELETE CASCADE,
    quantity   integer NOT NULL CHECK (quantity > 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX cart_items_cart_id_idx ON cart_items (cart_id);
CREATE INDEX cart_items_variant_id_idx ON cart_items (variant_id);
CREATE UNIQUE INDEX cart_items_loose_variant_uidx ON cart_items (cart_id, variant_id) WHERE set_id IS NULL;
CREATE UNIQUE INDEX cart_items_set_member_uidx ON cart_items (cart_id, set_id, variant_id) WHERE set_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Orders
-- ---------------------------------------------------------------------------

CREATE TABLE orders (
    id                      uuid PRIMARY KEY,
    user_id                 uuid REFERENCES users (id) ON DELETE SET NULL,
    guest_email             text,
    email_norm              text,
    cart_id                 uuid REFERENCES carts (id) ON DELETE SET NULL,
    status                  order_status NOT NULL DEFAULT 'pending_payment',
    subtotal_cents          bigint NOT NULL DEFAULT 0,
    shipping_cents          bigint NOT NULL DEFAULT 0,
    discount_cents          bigint NOT NULL DEFAULT 0,
    pix_discount_cents      bigint NOT NULL DEFAULT 0,
    total_cents             bigint NOT NULL DEFAULT 0,
    shipping_address        jsonb,
    notes                   text,
    payment_meta            jsonb,
    coupon_id               uuid REFERENCES coupons (id) ON DELETE SET NULL,
    reservation_expires_at  timestamptz,
    access_token            uuid NOT NULL DEFAULT gen_random_uuid(),
    access_token_expires_at timestamptz NOT NULL DEFAULT (now() + interval '90 days'),
    paid_at                 timestamptz,
    -- Payments (static PIX or Mercado Pago).
    payment_provider        text NOT NULL DEFAULT 'static_pix'
        CONSTRAINT orders_payment_provider_check CHECK (payment_provider IN ('static_pix', 'mercadopago')),
    mp_payment_id           bigint,
    mp_status               text,
    mp_status_detail        text,
    mp_qr_code              text,
    mp_qr_code_base64       text,
    mp_ticket_url           text,
    mp_expires_at           timestamptz,
    mp_synced_at            timestamptz,
    -- Fulfillment.
    carrier                 text NOT NULL DEFAULT 'Correios',
    tracking_code           text,
    shipped_at              timestamptz,
    delivered_at            timestamptz,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX orders_access_token_uidx ON orders (access_token);
CREATE UNIQUE INDEX orders_mp_payment_id_uidx ON orders (mp_payment_id) WHERE mp_payment_id IS NOT NULL;
CREATE INDEX orders_user_id_idx ON orders (user_id);
CREATE INDEX orders_coupon_id_idx ON orders (coupon_id);
CREATE INDEX orders_status_idx ON orders (status);
CREATE INDEX orders_created_at_idx ON orders (created_at);
CREATE INDEX orders_pending_cart_id_idx ON orders (cart_id) WHERE status = 'pending_payment';
CREATE INDEX orders_pending_email_norm_idx ON orders (email_norm) WHERE status = 'pending_payment';
CREATE INDEX orders_reservation_expires_at_idx ON orders (reservation_expires_at)
    WHERE status = 'pending_payment' AND reservation_expires_at IS NOT NULL;
-- Sales reports bucket by COALESCE(paid_at, created_at) over sold statuses.
CREATE INDEX orders_sale_at_idx ON orders (COALESCE(paid_at, created_at))
    WHERE status IN ('paid', 'processing', 'shipped', 'delivered');

CREATE TABLE order_items (
    id               uuid PRIMARY KEY,
    order_id         uuid NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    variant_id       uuid NOT NULL REFERENCES product_variants (id) ON DELETE RESTRICT,
    product_name     text NOT NULL,
    variant_label    text NOT NULL,
    quantity         integer NOT NULL,
    unit_price_cents bigint NOT NULL,
    set_id           uuid,
    set_name         text,
    created_at       timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX order_items_order_id_idx ON order_items (order_id);
CREATE INDEX order_items_variant_id_idx ON order_items (variant_id);

CREATE TABLE inventory_reservations (
    id           uuid PRIMARY KEY,
    order_id     uuid NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    inventory_id uuid NOT NULL REFERENCES inventory (id),
    quantity     integer NOT NULL CHECK (quantity > 0),
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX inventory_reservations_inventory_id_idx ON inventory_reservations (inventory_id);
CREATE INDEX inventory_reservations_order_id_idx ON inventory_reservations (order_id);

CREATE TABLE coupon_redemptions (
    id          uuid PRIMARY KEY,
    coupon_id   uuid NOT NULL REFERENCES coupons (id) ON DELETE CASCADE,
    user_id     uuid REFERENCES users (id) ON DELETE SET NULL,
    order_id    uuid NOT NULL UNIQUE REFERENCES orders (id) ON DELETE CASCADE,
    guest_email text,
    email_norm  text,
    refunded_at timestamptz,
    redeemed_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX coupon_redemptions_coupon_id_idx ON coupon_redemptions (coupon_id);
CREATE INDEX coupon_redemptions_user_id_idx ON coupon_redemptions (user_id);
CREATE INDEX coupon_redemptions_coupon_user_idx ON coupon_redemptions (coupon_id, user_id);
CREATE INDEX coupon_redemptions_active_idx ON coupon_redemptions (coupon_id) WHERE refunded_at IS NULL;
CREATE INDEX coupon_redemptions_email_norm_idx ON coupon_redemptions (coupon_id, email_norm)
    WHERE email_norm IS NOT NULL AND refunded_at IS NULL;
CREATE INDEX coupon_redemptions_guest_email_idx ON coupon_redemptions (coupon_id, guest_email)
    WHERE guest_email IS NOT NULL AND refunded_at IS NULL;

-- Deleting a user keeps the contact address on their orders.
-- +goose StatementBegin
CREATE FUNCTION orders_keep_contact_on_user_delete() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE orders
    SET guest_email = OLD.email
    WHERE user_id = OLD.id
      AND (guest_email IS NULL OR btrim(guest_email) = '');
    RETURN OLD;
END
$$;
-- +goose StatementEnd

CREATE TRIGGER users_keep_order_contact
    BEFORE DELETE ON users
    FOR EACH ROW EXECUTE FUNCTION orders_keep_contact_on_user_delete();

-- Live sellable quantity of one inventory row: on-hand minus holds, where
-- holds of expired-but-not-yet-swept pending orders no longer count. Same
-- expression as the Rust `LIVE_AVAILABLE_SQL`; call it as
-- `inventory_live_available(i.id, i.quantity, i.reserved)`.
-- +goose StatementBegin
CREATE FUNCTION inventory_live_available(p_inventory_id uuid, p_quantity integer, p_reserved integer)
    RETURNS integer
    LANGUAGE sql
    STABLE
AS $$
    SELECT GREATEST(p_quantity - GREATEST(p_reserved - COALESCE((
        SELECT SUM(r.quantity)::integer
        FROM inventory_reservations r
        INNER JOIN orders o ON o.id = r.order_id
        WHERE r.inventory_id = p_inventory_id
          AND o.status = 'pending_payment'
          AND o.reservation_expires_at < now()), 0), 0), 0)
$$;
-- +goose StatementEnd

-- Inventory rows with their live availability (see function above).
CREATE VIEW inventory_live AS
SELECT
    i.id,
    i.variant_id,
    i.warehouse_id,
    i.quantity,
    i.reserved,
    inventory_live_available(i.id, i.quantity, i.reserved) AS live_available
FROM inventory i;

-- Product card columns shared by every storefront listing (catalog,
-- wishlist, related products, looks, set members): the Rust
-- PRODUCT_SUMMARY_COLUMNS fragment as a view, so the sqlc queries select
-- from it instead of repeating the subqueries. A simple view is flattened
-- by the planner; its subqueries only run for the rows a query returns.
--
-- available_total is raw stock (quantity - reserved over active
-- warehouses), not inventory_live_available: cards and the in-stock filter
-- ignore not-yet-swept expired holds, as in Rust.
CREATE VIEW product_summaries AS
SELECT
    p.id,
    p.name,
    p.slug,
    p.description,
    p.price_in_cents,
    p.compare_at_price_in_cents,
    p.category,
    p.active,
    p.featured,
    p.created_at,
    (SELECT pi.url FROM product_images pi
     WHERE pi.product_id = p.id
     ORDER BY pi.sort_order ASC LIMIT 1)::null_text AS image_url,
    (SELECT pi.url FROM product_images pi
     WHERE pi.product_id = p.id
     ORDER BY pi.sort_order ASC LIMIT 1 OFFSET 1)::null_text AS secondary_image_url,
    COALESCE((
        SELECT SUM(GREATEST(i.quantity - i.reserved, 0))::int
        FROM inventory i
        INNER JOIN warehouses w ON w.id = i.warehouse_id
        WHERE i.variant_id IN (SELECT pv.id FROM product_variants pv WHERE pv.product_id = p.id)
          AND w.active = true), 0)::int AS available_total,
    COALESCE(
        (SELECT json_agg(json_build_array(pv.color, pv.color_hex) ORDER BY pv.color ASC)
         FROM (SELECT DISTINCT ON (pv.color) pv.color, pv.color_hex
               FROM product_variants pv
               WHERE pv.product_id = p.id
               ORDER BY pv.color ASC, pv.color_hex ASC) pv),
        '[]'::json
    )::text AS colors_json
FROM products p;

-- ---------------------------------------------------------------------------
-- Returns / exchanges
-- ---------------------------------------------------------------------------

CREATE TABLE return_requests (
    id               uuid PRIMARY KEY,
    order_id         uuid NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
    user_id          uuid REFERENCES users (id) ON DELETE SET NULL,
    kind             text NOT NULL CHECK (kind IN ('exchange', 'return', 'defect')),
    status           text NOT NULL DEFAULT 'requested'
        CHECK (status IN ('requested', 'approved', 'received', 'resolved', 'rejected')),
    resolution       text CHECK (resolution IN ('refunded', 'exchanged')),
    reason           text NOT NULL CHECK (char_length(reason) >= 1 AND char_length(reason) <= 1000),
    desired_size     text CHECK (char_length(desired_size) <= 20),
    instructions     text,
    rejection_reason text,
    refund_cents     bigint CHECK (refund_cents >= 0),
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    approved_at      timestamptz,
    received_at      timestamptz,
    resolved_at      timestamptz,
    CONSTRAINT return_requests_resolution_matches_status CHECK ((status = 'resolved') = (resolution IS NOT NULL))
);
CREATE INDEX return_requests_order_idx ON return_requests (order_id);
CREATE INDEX return_requests_status_created_idx ON return_requests (status, created_at DESC);
CREATE UNIQUE INDEX return_requests_open_order_uidx ON return_requests (order_id)
    WHERE status IN ('requested', 'approved', 'received');

CREATE TABLE return_request_items (
    return_request_id uuid NOT NULL REFERENCES return_requests (id) ON DELETE CASCADE,
    order_item_id     uuid NOT NULL REFERENCES order_items (id) ON DELETE CASCADE,
    quantity          integer NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (return_request_id, order_item_id)
);
CREATE INDEX return_request_items_order_item_idx ON return_request_items (order_item_id);

-- ---------------------------------------------------------------------------
-- Reviews, wishlist, stock alerts, newsletter
-- ---------------------------------------------------------------------------

CREATE TABLE product_reviews (
    id           uuid PRIMARY KEY,
    product_id   uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    user_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    order_id     uuid REFERENCES orders (id) ON DELETE SET NULL,
    rating       smallint NOT NULL CHECK (rating >= 1 AND rating <= 5),
    title        text NOT NULL CHECK (char_length(title) >= 1 AND char_length(title) <= 80),
    body         text NOT NULL CHECK (char_length(body) >= 1 AND char_length(body) <= 2000),
    fit          review_fit,
    status       review_status NOT NULL DEFAULT 'pending',
    created_at   timestamptz NOT NULL DEFAULT now(),
    moderated_at timestamptz,
    moderated_by uuid REFERENCES users (id) ON DELETE SET NULL,
    CONSTRAINT product_reviews_user_product_uidx UNIQUE (user_id, product_id)
);
CREATE INDEX product_reviews_approved_idx ON product_reviews (product_id, created_at DESC) WHERE status = 'approved';
CREATE INDEX product_reviews_status_idx ON product_reviews (status, created_at);

CREATE TABLE wishlist_items (
    user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    product_id uuid NOT NULL REFERENCES products (id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, product_id)
);

CREATE TABLE stock_alerts (
    id          uuid PRIMARY KEY,
    variant_id  uuid NOT NULL REFERENCES product_variants (id) ON DELETE CASCADE,
    email_norm  text NOT NULL,
    user_id     uuid REFERENCES users (id) ON DELETE CASCADE,
    created_at  timestamptz NOT NULL DEFAULT now(),
    notified_at timestamptz
);
CREATE UNIQUE INDEX stock_alerts_active_uidx ON stock_alerts (variant_id, email_norm) WHERE notified_at IS NULL;
CREATE INDEX stock_alerts_pending_email_idx ON stock_alerts (email_norm) WHERE notified_at IS NULL;

CREATE TABLE newsletter_subscribers (
    id              uuid PRIMARY KEY,
    email           text NOT NULL,
    name            text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    unsubscribed_at timestamptz
);
CREATE UNIQUE INDEX newsletter_subscribers_email_lower_idx ON newsletter_subscribers (lower(email));

-- ---------------------------------------------------------------------------
-- Mail outbox (transactional email, delivered by the background worker)
-- ---------------------------------------------------------------------------

CREATE TABLE email_outbox (
    id              uuid PRIMARY KEY,
    kind            text NOT NULL,
    to_address      text NOT NULL,
    subject         text NOT NULL,
    html_body       text NOT NULL,
    text_body       text NOT NULL,
    status          text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed')),
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    dedupe_key      text,
    created_at      timestamptz NOT NULL DEFAULT now(),
    sent_at         timestamptz
);
CREATE UNIQUE INDEX email_outbox_dedupe_key_uidx ON email_outbox (dedupe_key) WHERE dedupe_key IS NOT NULL;
CREATE INDEX email_outbox_due_idx ON email_outbox (next_attempt_at) WHERE status = 'pending';
CREATE INDEX email_outbox_kind_recipient_idx ON email_outbox (kind, lower(to_address), created_at);
CREATE INDEX email_outbox_recipient_recent_idx ON email_outbox (lower(to_address), created_at);
